import ast,hashlib,json,pathlib,subprocess
root=pathlib.Path('/workspace')
p=json.loads(root.joinpath('proposal.json').read_text())
r=json.loads(subprocess.check_output(['python3','/workspace/tools.py','resolve','run://r-001'],text=True))
w=json.loads(subprocess.check_output(['python3','/workspace/tools.py','resolve','workspace://w-001'],text=True))
errors=[]
def check(ok,msg):
 if not ok:errors.append(msg)
def validate(value,schema,path):
 typ=schema.get('type')
 valid={'object':lambda:isinstance(value,dict),'array':lambda:isinstance(value,list),'string':lambda:isinstance(value,str),'boolean':lambda:isinstance(value,bool)}
 if typ:check(valid[typ](),path+' type')
 if 'const' in schema:check(value==schema['const'],path+' const')
 if 'enum' in schema:check(value in schema['enum'],path+' enum')
 if isinstance(value,str):check(len(value)>=schema.get('minLength',0),path+' minLength')
 if isinstance(value,list):
  check(len(value)>=schema.get('minItems',0),path+' minItems')
  for i,v in enumerate(value):validate(v,schema.get('items',{}),path+'.'+str(i))
 if isinstance(value,dict):
  for k in schema.get('required',[]):check(k in value,path+' missing '+k)
  if schema.get('additionalProperties') is False:check(not(set(value)-set(schema.get('properties',{}))),path+' extra properties')
  for k,v in value.items():
   if k in schema.get('properties',{}):validate(v,schema['properties'][k],path+'.'+k)
validate(p['study'],r['study_schema'],'study')
check(p['study']['protocol_ref']==r['required_study_protocol_ref'],'protocol')
check(p['parent_trial'] in r['context']['allowed_observation_ids'],'parent')
check(set(p['study']['evidence_refs'])<=set(r['context']['allowed_observation_ids']),'evidence IDs')
check(1<=len(p['variants'])<=4 and any(v['role']=='candidate' for v in p['variants']),'variants')
check(len({v['file'] for v in p['variants']})==len(p['variants']),'distinct file')
check(len({v['name'] for v in p['variants']})==len(p['variants']),'distinct name')
parsed=[]
def normalized_literal(x):return json.loads(json.dumps(x))
for v in p['variants']:
 file=root/v['file'];s=file.read_text();t=ast.parse(s);compile(s,str(file),'exec')
 check(file.name==v['file'] and file.suffix=='.py','basename '+str(file))
 cfg_node=next(n for n in t.body if isinstance(n,ast.Assign) and any(isinstance(k,ast.Name) and k.id=='CONFIG' for k in n.targets))
 cfg=ast.literal_eval(cfg_node.value)
 check(cfg==v['config'],'config '+file.name)
 init=next(n for n in ast.walk(t) if isinstance(n,ast.FunctionDef) and n.name=='__init__')
 defaults=dict(zip([a.arg for a in init.args.args][-len(init.args.defaults):],init.args.defaults))
 for k,val in cfg.items():check(k in defaults and normalized_literal(ast.literal_eval(defaults[k]))==val,'default '+file.name+' '+k)
 for n in ast.walk(t):
  if isinstance(n,(ast.Import,ast.ImportFrom)):
   mods=[n.module] if isinstance(n,ast.ImportFrom) else [x.name for x in n.names]
   check(all(x.split('.')[0] in {'torch','numpy','math','typing','copy','functools','collections','itertools','dataclasses','contextlib','unirank','model_zoo'} for x in mods),'imports '+file.name)
  if isinstance(n,ast.Call) and isinstance(n.func,ast.Name):check(n.func.id not in {'open','eval','exec','compile','__import__'},'forbidden call '+file.name)
 cfg_node.value=ast.Constant(value=None)
 for k in ['within_block_readout','block_aux_adapter_context_grad']:defaults[k].value=None
 parsed.append(ast.dump(t,include_attributes=False))
check(len(set(parsed))==1,'factorial executable AST parity')
ancestor=ast.parse(root.joinpath('history_g0_r0056_uniform_bridge.py').read_text())
current=ast.parse(root.joinpath('candidate.py').read_text())
def methods(t):return {n.name:n for n in next(n for n in t.body if isinstance(n,ast.ClassDef) and n.name=='Model').body if isinstance(n,ast.FunctionDef)}
a,b=methods(ancestor),methods(current)
for name in set(a)&set(b)-{'__init__','forward','_context_history_correction'}:check(ast.dump(a[name])==ast.dump(b[name]),'inherited method '+name)
def module_calls(t):
 return [ast.dump(n) for n in ast.walk(t) if isinstance(n,ast.Call) and isinstance(n.func,ast.Attribute) and isinstance(n.func.value,ast.Name) and n.func.value.id=='nn']
check(module_calls(a['__init__'])==module_calls(b['__init__']),'learned module construction/order')
for entry in w['available_ancestor_sources']:
 check(hashlib.sha256(root.joinpath(entry['file']).read_bytes()).hexdigest()==entry['source_sha256'],'ancestor digest '+entry['file'])
check(hashlib.sha256(root.joinpath('baseline_reference.py').read_bytes()).hexdigest()=='f4b473cbacf60d72cff90f3721ad754dd617ee6065fe3fca2fc9cd4be2b25c36','baseline digest')
check({x['knowledge_id'] for x in p['knowledge_assessments']}=={'unirank-method-'+x for x in ['hiformer','longer','unimixer','onetrans','zenith','est']},'knowledge coverage')
if errors:raise SystemExit('\\n'.join(errors))
print('PASS: study schema, authorized IDs/protocol, four syntax checks, CONFIG/defaults, factorial AST, allowed imports/no direct I/O, inherited helpers, nn module construction/order, all ancestor/baseline hashes, six knowledge assessments.')
p['notes']+='\\nLocal static validation passed: recursive supplied study-schema checks; authorized protocol/parent/evidence IDs; all four modules compile in memory; CONFIG/proposal/constructor defaults agree; executable factorial ASTs differ only in CONFIG and the two declared defaults; allowed imports/no direct I/O; every shared inherited helper other than constructor/forward/correction matches r0056 uniform bridge; learned nn construction expressions/order unchanged; all seven ancestor digests and baseline_reference digest preserved; six industry assessments present. These do not establish native tensor/autograd/state/data/performance correctness.'
root.joinpath('proposal.json').write_text(json.dumps(p,indent=2)+'\\n')
PY"

